// The label-change variant: an `update` action whose `changes.labels` record
// carries the before/after sets (docs' Issue Hook update example shape); the
// post-change `labels[]` is what the label policy reads.
export const issueLabeled = {
  ...issueOpened,
  object_attributes: {
    ...issueOpened.object_attributes,
    action: "update",
    label: { ...workLabel },
    changes: {
      labels: {
        previous: [] as unknown[],
        current: [workLabel],
      },
    },
    labels: [workLabel],
    updated_at: "2013-12-04T10:00:00.000Z",
  },
};

